{
  "title": "agent.completions.message.AssistantToolCallFunctionExpression",
  "description": "Expression variant of [`AssistantToolCallFunction`] for dynamic content.",
  "type": "object",
  "properties": {
    "arguments": {
      "description": "The arguments expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    },
    "name": {
      "description": "The function name expression.

A value that can be either a literal or an expression.

This allows Function definitions to mix static values with dynamic
expressions. During compilation, expressions are evaluated while
literal values pass through unchanged.

# Example

Literal value:
```json
"hello world"
```

JMESPath expression:
```json
{"$jmespath": "input.greeting"}
```

Starlark expression:
```json
{"$starlark": "input['greeting']"}
```",
      "anyOf": [
        {
          "title": "Expression",
          "description": "An expression (JMESPath or Starlark) to evaluate.",
          "$ref": "functions.expression.Expression"
        },
        {
          "title": "Value",
          "description": "A literal value.",
          "type": "string"
        }
      ]
    }
  }
}

{
  "title": "agent.completions.message.RichContent",
  "description": "Rich content for user/assistant messages (supports multimodal input).",
  "anyOf": [
    {
      "title": "Text",
      "description": "Plain text content.",
      "type": "string"
    },
    {
      "title": "Parts",
      "description": "Multi-part content (text, images, audio, video, files).",
      "type": "array",
      "items": {
        "$ref": "agent.completions.message.RichContentPart"
      }
    }
  ]
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}

{
  "title": "agent.completions.message.ImageUrl",
  "description": "An image URL for multimodal input.",
  "type": "object",
  "properties": {
    "detail": {
      "description": "The detail level for image processing.",
      "anyOf": [
        {
          "$ref": "agent.completions.message.ImageUrlDetail"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "url": {
      "description": "The URL of the image (can be a data URL or HTTP URL).",
      "type": "string"
    }
  }
}

{
  "title": "functions.expression.IntegerInputSchema",
  "description": "Schema for an integer input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the integer.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "maximum": {
      "description": "Maximum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "integer",
          "minimum": -9223372036854775808,
          "maximum": 9223372036854775807
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "minimum": {
      "description": "Minimum allowed value (inclusive).",
      "anyOf": [
        {
          "type": "integer",
          "minimum": -9223372036854775808,
          "maximum": 9223372036854775807
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.IntegerInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.Special",
  "description": "Predefined expression behaviors that require no user-authored code.",
  "anyOf": [
    {
      "title": "Input",
      "description": "Returns the params input as-is.",
      "type": "string",
      "enum": [
        "input"
      ]
    },
    {
      "title": "Output",
      "description": "Returns the params output as-is.",
      "type": "string",
      "enum": [
        "output"
      ]
    },
    {
      "title": "TaskOutputL1Normalized",
      "description": "L1-normalizes the output. Scalar/Err pass through.\nVector: L1 normalize. Vectors: L1 normalize each.",
      "type": "string",
      "enum": [
        "task_output_l1_normalized"
      ]
    },
    {
      "title": "TaskOutputWeightedSum",
      "description": "Weighted sum of the output. Vector → Scalar. Vectors → Vector.",
      "type": "string",
      "enum": [
        "task_output_weighted_sum"
      ]
    },
    {
      "title": "InputItemsOutputLength",
      "description": "Returns the length of input['items'] as u64",
      "type": "string",
      "enum": [
        "input_items_output_length"
      ]
    },
    {
      "title": "InputItemsOptionalContextSplit",
      "description": "Splits an input containing items and optionally context into multiple inputs",
      "type": "string",
      "enum": [
        "input_items_optional_context_split"
      ]
    },
    {
      "title": "InputItemsOptionalContextMerge",
      "description": "Merges multiple inputs containing items and optionally context into a single input",
      "type": "string",
      "enum": [
        "input_items_optional_context_merge"
      ]
    }
  ]
}

